// Bounded analysis records are separate from the educational ontology.
function comparisonHtml(){
  const records=comparisons.records, provisional=records.filter(r=>r.status==='PROVISIONAL').length;
  return `<div class="section-head"><h2>Three subjects, three comparisons</h2><span>${provisional} candidate analogy · ${records.length-provisional} rejected equivalences · 0 accepted links</span></div><p>Compare what each expectation asks a student to do, not just the words it uses. These are builder-reviewed analysis records awaiting the separate AI audit. They do not change either student's expectations or create graph edges.</p>${records.map(r=>`<details class="comparison-card" id="${esc(r.id)}"><summary><span class="comparison-heading">${esc(r.title)}</span><span class="comparison-verdict">${esc(r.disposition_label)}</span></summary><p class="muted">${esc(r.subjects.join(' / '))} · ${esc(r.id)}</p><h3>Proposal tested</h3><p>${esc(r.proposal)}</p><h3>What the sources support in common</h3><p>${esc(r.commonality)}</p><div class="comparison-sources">${r.evidence.map((e,i)=>`<section><h3>${esc(r.subjects[i])} · ${esc(node(e.standard_id).label)}</h3><blockquote>${esc(e.quotation)}</blockquote>${row(e.standard_id,'Open source Receipt · page '+e.pdf_page)}${row(e.node_id,'Open the parsed expectation')}</section>`).join('')}</div><h3>Where the requirements differ</h3><div class="comparison-axes">${r.axes.map(a=>`<section><h4>${esc(a.axis)}</h4><div><p><b>${esc(r.subjects[0])}</b> ${esc(a.left)}</p><p><b>${esc(r.subjects[1])}</b> ${esc(a.right)}</p></div></section>`).join('')}</div><h3>Disposition</h3>${badge(r.status)}<p>${esc(r.decision)}</p><h3>What is not established</h3><p>${esc(r.not_established)}</p><h3>Source connection check</h3><p>${esc(r.source_context)}</p><h3>What would move this forward</h3><p>${esc(r.next_evidence)}</p><p class="muted">${esc(r.review_status)}. Evidence snapshots are tied to the archived source hashes and the specific source/parsed records. A later change requires rechecking the comparison.</p></details>`).join('')}<details class="methodology"><summary>Method and limits</summary><p>${esc(comparisons.scope)} We compared action, object, evidence, required product, placement, and boundary. Similarity is not equivalence; source cross-references are not automatically prerequisites. A rejection applies to the stated proposal, not every possible relationship between the subjects.</p><p>Grades 6–8 science placement stays separate from Grade 7 mathematics and ELA. No mastery, transfer, developmental sequence or shared capability hierarchy is asserted.</p><p><a href="evidence/science-full/page-34.png" target="_blank" rel="noopener">Inspect the science source's own connection box</a> · <a href="${gitPath('docs/wednesday-comparisons.md')}" target="_blank" rel="noopener">Comparison record and review limits</a></p></details>`;
}
